/**
 * Stock RM FF 2569.xlsx: immutable UI mock source snapshots.
 *
 * Reads each worksheet's saved numeric values and cached formula results;
 * does not recalculate or infer Excel formulas. An empty Excel cell stays
 * an empty string, while a cached numeric zero stays "0".
 *
 * 14 stock sheets: "ST.RM 68 " (real trailing space), "ST.RM 69", Jan-Dec.
 * The fifteenth sheet, "สรุปยอดรับ FF 69", is a separate receipt report.
 *
 * Only days with entered movements are stored, and monthly dates outside
 * the real calendar are not synthesized. See stockRmMockImportWarnings for
 * explicit notes about source cells that cannot be mapped to valid dates.
 * Whitespace-only entries are treated as blank, never as numeric zero.
 *
 * UI MOCK ONLY: no API, database, browser storage, or automatic balances.
 */

