/**
 * Visible data-quality exceptions in the original Excel workbook.
 * Out-of-calendar-day values are not assigned to another date automatically.
 */
export const stockRmMockImportWarnings = [
  {
    source_sheet_name: "Apr",
    cell: "FY12",
    code_new: "1104",
    value: "10",
    reason: "The 31st day is outside Apr 2026; not mapped to a date.",
  },
] as const;

/** All item codes known by December, including newly added RM codes. */
export const stockRmMockItems: readonly StockRmItem[] =
  SOURCE_SHEETS[SOURCE_SHEETS.length - 1]?.rows.map(([no, code_new]) => ({
    no,
    code_new,
    name: null,
  })) ?? [];

function movementFromSource([
  ,
  received_weight,
  received_value,
  issued_for_production,
  issued_adjustment,
  issued_discarded,
]: SourceMovement): StockRmMovementValues {
  return {
    received_weight,
    received_value,
    issued_for_production,
    issued_adjustment,
    issued_discarded,
  };
}

function summaryFromSource(values: readonly string[]): StockRmSummaryValues {
  const summary = blankStockRmSummary();
  STOCK_RM_SUMMARY_FIELDS.forEach((field, index) => {
    summary[field] = values[index] ?? "";
  });
  return summary;
}

function dateForDay(month: number, day: number): string {
  return `2026-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
}

/** Returns fresh, unshared React-State-ready objects on every call. */
export function createStockRmMockSheets(): StockRmSheet[] {
  return SOURCE_SHEETS.map(({ period, rows }) => ({
    id: stockRmPeriodKey(period),
    period: { ...period },
    source_sheet_name: stockRmSourceSheetName(period),
    created_at: "",
    updated_at: "",
    rows: rows.map(([no, code_new, summary, remark, movements]) => ({
      item: { no, code_new, name: null },
      summary: summaryFromSource(summary),
      remark,
      daily:
        period.view === "MONTH"
          ? movements.map((movement) => ({
              date: dateForDay(period.month, movement[0]),
              values: movementFromSource(movement),
            }))
          : [],
      year_months:
        period.view === "YEAR"
          ? movements.map((movement) => ({
              month: movement[0] as (typeof STOCK_RM_MONTHS)[number],
              values: movementFromSource(movement),
            }))
          : [],
    })),
  }));
}

/** The original receipt summary is a separate report, not a stock sheet. */
export function createStockRmMockReceiptReport(): StockRmReceiptReport {
  return {
    source_sheet_name: STOCK_RM_RECEIPT_REPORT_SHEET,
    year_be: 2569,
    rows: SOURCE_RECEIPT_ROWS.map(([no, code_new, annual, monthValues]) => ({
      item: { no, code_new, name: null },
      annual: { weight: annual[0], value: annual[1] },
      months: STOCK_RM_MONTHS.map((month, index) => ({
        month,
        values: {
          weight: monthValues[index]?.[0] ?? "",
          value: monthValues[index]?.[1] ?? "",
        },
      })),
    })),
  };
}
